.link-primary {
  text-decoration: underline;
  text-underline-offset: 0.2em; /* Lifts the underline to prevent cutting descenders */
  text-decoration-thickness: 1px; /* Ensures a subtle, readable line weight */
  color: var(--link-color, #0066cc);
}

.link-primary:hover {
  text-decoration-color: var(--link-hover-color, #004499);
  text-underline-offset: 0.25em; /* Subtle lift on hover */
}
